extensions={'Gamete','Tunica albuginea','Spermatogonium','Primary spermatocyte','Secondary spermatocyte','Spermatid','Spermiogenesis','Sertoli cell','Leydig cell','Androgen','Deferent ampulla','Ejaculatory duct','Male urethra','Membranous urethra','Prostate','Seminal fructose','Acrosome','Haploid state','Meiosis','GnRH','FSH','Inhibin','Puberty','Corpus spongiosum','Erection','Ejaculation','Prostate cancer','Perimetrium','Endometrium','Granulosa cell','Theca cell','Zona pellucida','Primary oocyte','Secondary oocyte','Oogonium','Oogenesis','Primary follicle','Follicular phase','LH surge','Luteal phase','Corpus luteum','Estrogen','Progesterone','Menses','Uterine tube','Tubal infundibulum','Fertilization','Zygote','Implantation','hCG','Lactation','Prolactin','Oxytocin','HPV'}
for i,(s,name,definition,detail,false,blank,answer) in enumerate(rows):
    s=[int(n) for n in s.split(',')] if ',' in s else int(s);clinical=name in extensions;e=f'{name}: {definition}. {detail}.'
    others=[r[1] for r in rows if r[1]!=name]
    c(s,f'Which reproductive term describes {definition}?',name,'|'.join(others[(i+j)%len(others)] for j in [13,27,41]),e,clinical)
    label=name if name in {'GnRH','LH','FSH','hCG','HPV'} else name.lower()
    c(s,f'Which reproductive statement about {label} is accurate?',detail,false,e,clinical)
    b(s,blank,answer,e,clinical)
