extras=[line.split('~') for line in EXTRA.splitlines() if line]
assert len(extras)==40,len(extras)
for s,p,a,w,e in extras:c([int(n) for n in s.split(',')],p,a,w,e,True)
assert len(questions)==600,len(questions)
assert len({q['question'].casefold() for q in questions})==600
# Cancer-related slides lack specific pathology figures. Use relevant normal
# anatomy instead of illustrating a different condition.
for question in questions:
    if question['source']['slides']==[21]:question['figure_slide']=6
    elif all(slide in {49,50} for slide in question['source']['slides']):question['figure_slide']=47
    elif question['source']['slides']==[44]:question['figure_slide']=43
Path('study-data/reproductive.json').write_text(json.dumps(questions,ensure_ascii=False,indent=2)+'\n')
print(len(questions),dict(Counter(q['type'] for q in questions)))
